'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {readAccountingSetup,type AccountingSetup} from '@/lib/accounting';
import {openingCents} from '@/lib/financial-opening-action';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {applicationUuid,validateInvoiceApplication,invoiceApplicationReceipt,invoiceApplicationStatus,type InvoiceApplication} from '@/lib/opening-invoice-application';
type Props={scope:HandoffScope;reservation:string;rows:{id:string;category:string;reference:string;remaining:string}[];onLocked:(v:boolean)=>void;onCompleted:()=>void};
export function FinancialInvoiceApplication(props:Props){return <Form key={[props.scope.tenant,props.scope.property,props.scope.actor,props.reservation].join(':')} {...props}/>}
function Form({scope,reservation,rows,onLocked,onCompleted}:Props){
 const [pending,setPending]=useState<InvoiceApplication|null>(null),[review,setReview]=useState<InvoiceApplication|null>(null),[setup,setSetup]=useState<AccountingSetup|null>(null),[invoices,setInvoices]=useState<{invoice_id:string;number:string}[]>([]),[opening,setOpening]=useState(''),[invoice,setInvoice]=useState(''),[amount,setAmount]=useState(''),[date,setDate]=useState(''),[period,setPeriod]=useState(''),[receivable,setReceivable]=useState(''),[reason,setReason]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const key=['irp.opening.invoice.v1',scope.tenant,scope.property,scope.actor,reservation].join(':'),alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const p=JSON.parse(raw);validateInvoiceApplication(p,scope,reservation);setPending(p)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore invoice application.')}return()=>{alive.current=false}},[key]);
 useEffect(()=>{onLocked(!ready||busy||!!pending)},[ready,busy,pending,onLocked]);
 function changed(){setReview(null);setConfirmed(false)}
 async function run(action:'load'|'review'|'post'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{const identify=async()=>{const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen the account.')};await identify();const base={p_tenant:scope.tenant,p_property:scope.property};
   if(action==='load'){const [s,list]=await Promise.all([hotelRpc('gl_setup',base),hotelRpc<Record<string,unknown>>('reservation_invoices',{...base,p_reservation:reservation})]);const parsed=readAccountingSetup(s,scope.tenant,scope.property);if(list.schema_version!==1||list.tenant_id!==scope.tenant||list.property_id!==scope.property||list.actor_id!==scope.actor||list.reservation_id!==reservation||list.complete!==true||!Array.isArray(list.invoices))throw Error('Invoice list does not match this stay.');const seen=new Set<string>();const values=list.invoices.map(v=>{if(!applicationUuid(v.invoice_id)||seen.has(v.invoice_id)||typeof v.number!=='string')throw Error('Invalid invoice list.');seen.add(v.invoice_id);return {invoice_id:v.invoice_id,number:v.number}});await identify();if(alive.current){setSetup(parsed);setInvoices(values)}return}
   if(action==='review'){const cents=openingCents(amount),selected=setup?.periods.find(p=>p.period_id===period&&!p.closed);if(!selected||date<selected.start_date||date>=selected.end_date_exclusive||!setup?.accounts.some(a=>a.account_id===receivable&&a.active&&a.kind==='asset')||!invoices.some(i=>i.invoice_id===invoice)||!rows.some(r=>r.id===opening&&['prepayment','security'].includes(r.category)))throw Error('Choose funds, invoice, account and an open period.');const value=await hotelRpc<Record<string,unknown>>('preview_opening_invoice_application',{...base,p_opening:opening,p_invoice:invoice,p_amount:cents,p_date:date});const p={id:crypto.randomUUID(),scope,reservation,opening,invoice,amount:String(cents),date,period,receivable,reason:reason.trim(),review:value};validateInvoiceApplication(p,scope,reservation);await identify();if(alive.current){setReview(p);setConfirmed(false)}return}
   const p=pending??review;if(!p)throw Error('Review the application first.');validateInvoiceApplication(p,scope,reservation);let complete=false,cancelled=false;
   if(action==='post'){if(!confirmed)throw Error('Confirm the reviewed application.');if(!pending){if(sessionStorage.getItem(key))throw Error('Recover the existing application first.');sessionStorage.setItem(key,JSON.stringify(p));setPending(p)}invoiceApplicationReceipt(await hotelRpc('apply_opening_to_invoice',{...base,p_request:p.id,p_review:p.review,p_receivable:p.receivable,p_period:p.period,p_reason:p.reason}),p.id);complete=true}
   else{if(action==='cancel'){if(!cancelConfirmed)throw Error('Confirm cancellation.');await hotelRpc('cancel_opening_invoice_application',{...base,p_request:p.id,p_confirmed:true})}const status=invoiceApplicationStatus(await hotelRpc('opening_invoice_application_status',{...base,p_request:p.id}),p);complete=status.found===true;cancelled=status.cancelled===true}
   await identify();if(alive.current){if(complete||cancelled){sessionStorage.removeItem(key);setPending(null);setReview(null);setConfirmed(false);setCancelConfirmed(false);setMessage(complete?'Funds applied to invoice.':'Invoice application cancelled.');if(complete)onCompleted()}else setMessage('No posting found. Retry or cancel the saved request.')}
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to apply funds.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 const selected=pending??review;
 return <section aria-label="Apply migrated funds to invoice"><h4>Apply migrated funds to an invoice</h4><p>This allocates recorded prepaid funds or a security deposit. It does not collect a new payment.</p><button type="button" disabled={busy||!ready||!!pending} onClick={()=>void run('load')}>Load invoices and accounts</button><fieldset disabled={busy||!ready||!!pending}>
 <label>Source funds<select value={opening} onChange={e=>{setOpening(e.target.value);changed()}}><option value="">Choose funds</option>{rows.filter(r=>['prepayment','security'].includes(r.category)).map(r=><option key={r.id} value={r.id}>{r.reference} · {r.category} · {bankCloseMoney(r.remaining)}</option>)}</select></label>
 <label>Invoice<select value={invoice} onChange={e=>{setInvoice(e.target.value);changed()}}><option value="">Choose invoice</option>{invoices.map(i=><option key={i.invoice_id} value={i.invoice_id}>Invoice {i.number}</option>)}</select></label>
 <label>Receivable account<select value={receivable} onChange={e=>{setReceivable(e.target.value);changed()}}><option value="">Choose account</option>{setup?.accounts.filter(a=>a.active&&a.kind==='asset').map(a=><option key={a.account_id} value={a.account_id}>{a.code} · {a.name}</option>)}</select></label>
 <label>Application period<select value={period} onChange={e=>{setPeriod(e.target.value);changed()}}><option value="">Choose period</option>{setup?.periods.filter(p=>!p.closed).map(p=><option key={p.period_id} value={p.period_id}>{p.start_date} to {p.end_date_exclusive} (end excluded)</option>)}</select></label>
 <label>Application date<input type="date" value={date} onChange={e=>{setDate(e.target.value);changed()}}/></label><label>Amount to apply<input inputMode="decimal" value={amount} onChange={e=>{setAmount(e.target.value);changed()}}/></label><label>Application reason<input maxLength={500} value={reason} onChange={e=>{setReason(e.target.value);changed()}}/></label><button type="button" onClick={()=>void run('review')}>Review invoice application</button></fieldset>
 {selected&&<><p role="status">Apply {bankCloseMoney(selected.amount)} on {selected.date}. Available funds: {bankCloseMoney(String(selected.review.opening_available_minor))}. Invoice capacity: {bankCloseMoney(String(selected.review.invoice_available_minor))}.</p><label><input type="checkbox" disabled={busy} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this invoice application</label><button type="button" disabled={busy||!confirmed} onClick={()=>void run('post')}>{pending?'Retry invoice application':'Apply funds to invoice'}</button></>}
 {pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check invoice application outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if funds were not applied</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel invoice application</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
